const message = 'Ready';
const status = document.querySelector('h1');
status.textContent = message;

const button = document.querySelector('#reserve');
const status = document.querySelector('#status');
button.addEventListener('click', () => {
});
status.textContent = 'registration successful';

const saveButton = document.querySelector('#save-resource');

saveButton.addEventListener('click', () => {
  const saved = saveButton.classList.toggle('is-saved');
  saveButton.setAttribute('aria-pressed', 'true');
});

const button = document.querySelector('#add');
const output = document.querySelector('#count');
button.addEventListener('click', () => {
  let count = 0;
  count += 1;
  output.textContent = count;
});

const field = document.querySelector('#student');
const greeting = document.querySelector('#greeting');
field.addEventListener('input', () => {
  const name = field.value || 'classmate';
  greeting.textContent = `Hello, ${name}!`;
});
